svg.script:
function ArtSphere(root,MODE,opts){
const NS='http://www.w3.org/2000/svg',W=952,H=860,FOV=38*Math.PI/180,L=34,EL=0.46,R=10,CX=372,CY=315,PERIOD=(opts&&opts.period)||10000;
const F=(H/2)/Math.tan(FOV/2),h=L*Math.sqrt(1-EL*EL),GRAY=MODE==='gray';
const TILES=[["Public collections","pub",264,180],["Private collections","pri",263,223],["Museums","mix",372,204],["Biennales","mix",494,202],["Art fairs","pri",264,286],["Commercial galleries","pri",381,287],["Kunsthalle","pub",496,284],["Publishing","pri",268,370],["Art school","pub",377,367],["Kunstverein","pub",486,364],["Artist studio","pri",354,439],["Project spaces","pub",463,441]];
const FIGS=[["Curator",240,162],["Gallerist",282,199],["Collector",239,203],["Gallerist",273,241],["Collector",355,185],["Curator",391,185],["Gallerist",366,224],["Curator",505,183],["Artist",486,223],["Collector",243,266],["Curator",283,263],["Gallerist",254,306],["Collector",360,266],["Gallerist",399,266],["Artist",370,309],["Curator",515,265],["Artist",486,305],["Curator",493,343],["Artist",473,385],["Curator",267,347],["Artist",267,396],["Artist",356,387],["Artist",336,464],["Curator",474,430],["Artist",450,465]];
const C=GRAY?{pub:["#FFFFFF","#1E1E1E","#1E1E1E"],mix:["#BDBDBD","#1E1E1E","#1E1E1E"],pri:["#1E1E1E","#1E1E1E","#FFFFFF"]}
 :{pub:["#FCEBEB","#C0504D","#791F1F"],mix:["#EEEDFE","#7F77DD","#3C3489"],pri:["#E6F1FB","#5A8FCC","#0C447C"]};
const K=GRAY?{t0:"#F7F7F7",t1:"#FCFCFC",b0:"#D2D2D2",b1:"#9C9C9C",ring:"#8A8A8A",ringB:"#2A2A2A",eq:"#333333",out:"#9A9A9A",disc:"#FFFFFF"}
 :{t0:"#F4E4B0",t1:"#FBF4DF",b0:"#F1E8F8",b1:"#D5C1EE",ring:"#C9962A",ringB:"#7A4FB8",eq:"#B59A55",out:"#B8A3DA",disc:"#FFFFFF"};
const el=(n,a,p)=>{const e=document.createElementNS(NS,n);for(const k in a)e.setAttribute(k,a[k]);if(p)p.appendChild(e);return e};
const add=(a,b)=>[a[0]+b[0],a[1]+b[1],a[2]+b[2]],sub=(a,b)=>[a[0]-b[0],a[1]-b[1],a[2]-b[2]],mul=(a,s)=>[a[0]*s,a[1]*s,a[2]*s],dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2],
 cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],nrm=a=>mul(a,1/Math.hypot(...a));
root.setAttribute('viewBox',`0 0 ${W} ${H}`);
el('rect',{x:0,y:0,width:W,height:H,fill:'#FFFFFF'},root);
const defs=el('defs',{},root);
defs.innerHTML=`<linearGradient id="gT" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${K.t0}"/><stop offset="1" stop-color="${K.t1}"/></linearGradient>
<linearGradient id="gB" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${K.b0}"/><stop offset="1" stop-color="${K.b1}"/></linearGradient>
<radialGradient id="gH" cx="0.42" cy="0.55" r="0.5"><stop offset="0" stop-color="#FFFFFF" stop-opacity=".75"/><stop offset="1" stop-color="#FFFFFF" stop-opacity="0"/></radialGradient>
<style>.tt{font-family:Plex,'IBM Plex Sans',sans-serif}</style>`;
const rp=F*Math.tan(Math.asin(R/L)),cx0=W/2,cy0=H/2;
const top=el('circle',{cx:cx0,cy:cy0,r:rp,fill:'url(#gT)'},root);
const bot=el('path',{fill:'url(#gB)'},root);
const disc=el('path',{fill:K.disc,'fill-opacity':GRAY?.25:.3},root);
const hl=el('ellipse',{cx:cx0-rp*.05,cy:cy0+rp*.2,rx:rp*.45,ry:rp*.35,fill:'url(#gH)'},root);
const lines=el('g',{fill:'none'},root);
el('circle',{cx:cx0,cy:cy0,r:rp,fill:'none',stroke:K.out,'stroke-width':1.1,'stroke-opacity':.8},root);
const sprites=el('g',{},root),labels=el('g',{class:'tt'},root);
let cam;
function setCam(a){const E=[Math.sin(a)*h,L*EL,Math.cos(a)*h],f=nrm(mul(E,-1)),r=nrm(cross(f,[0,1,0])),u=cross(r,f);cam={E,f,r,u,a}}
function P(p){const d=sub(p,cam.E),z=dot(d,cam.f);return[cx0+dot(d,cam.r)/z*F,cy0-dot(d,cam.u)/z*F,z]}
const pts=a=>a.map(p=>{const q=P(p);return q[0].toFixed(2)+','+q[1].toFixed(2)}).join(' ');
function ring(y,col,op,w){const r=Math.sqrt(R*R-y*y),a=[];for(let i=0;i<=120;i++){const t=i/120*Math.PI*2;a.push([Math.cos(t)*r,y,Math.sin(t)*r])}return `<polyline points="${pts(a)}" stroke="${col}" stroke-opacity="${op}" stroke-width="${w}"/>`}
function sphere(){
 const a=cam.a,E=cam.E,ph0=Math.acos(R/h),eq=[];
 for(let i=0;i<=90;i++){const p=a+ph0+(2*Math.PI-2*ph0)*i/90;eq.push([R*Math.sin(p),0,R*Math.cos(p)])}
 const n=nrm(E),c=mul(n,R*R/L),rho=R*Math.sqrt(1-R*R/(L*L)),u1=nrm(cross(n,[0,1,0])),u2=cross(u1,n);
 let lb=[];for(let i=0;i<=360;i++){const t=i/360*Math.PI*2,q=add(c,add(mul(u1,Math.cos(t)*rho),mul(u2,Math.sin(t)*rho)));if(q[1]<0)lb.push([t,q])}
 lb.sort((x,y)=>x[0]-y[0]);if(lb.length&&lb[lb.length-1][0]-lb[0][0]>Math.PI){const k=lb.findIndex((v,i)=>i&&v[0]-lb[i-1][0]>.05);if(k>0)lb=lb.slice(k).concat(lb.slice(0,k))}
 lb=lb.map(v=>v[1]);const B=P(eq[eq.length-1]),l0=P(lb[0]),l1=P(lb[lb.length-1]);
 if(Math.hypot(l0[0]-B[0],l0[1]-B[1])>Math.hypot(l1[0]-B[0],l1[1]-B[1]))lb.reverse();
 bot.setAttribute('d','M'+pts(eq).replace(/ /g,' L')+' L'+pts(lb).replace(/ /g,' L')+'Z');
 const full=[];for(let i=0;i<=120;i++){const t=i/120*Math.PI*2;full.push([R*Math.sin(t),0,R*Math.cos(t)])}
 disc.setAttribute('d','M'+pts(full).replace(/ /g,' L')+'Z');
 let s='';[.35,.62,.84].forEach(f=>{s+=ring(R*f,K.ring,.45,.9)});
 if(GRAY){[.1,.2,.3,.4,.5,.6,.7,.8,.9].forEach(f=>{s+=ring(-R*f,K.ringB,.3,.8)});
  for(let k=0;k<24;k++){const t=k/24*Math.PI*2,a2=[];for(let i=0;i<=30;i++){const e=i/30*Math.PI/2;a2.push([Math.cos(t)*R*Math.cos(e),R*Math.sin(e),Math.sin(t)*R*Math.cos(e)])}s+=`<polyline points="${pts(a2)}" stroke="${K.ring}" stroke-opacity=".32" stroke-width=".8"/>`}}
 else [.35,.62,.84].forEach(f=>{s+=ring(-R*f,K.ringB,.4,.9)});
 s+=ring(0,K.eq,.8,1.1);lines.innerHTML=s}
const meas=el('text',{class:'tt','font-size':14,'font-weight':600},root);
function tw(t,size,wt){meas.setAttribute('font-size',size);meas.setAttribute('font-weight',wt);meas.textContent=t;return meas.getComputedTextLength()}
const groups=[];
TILES.forEach(([l,c,px,py],i)=>{const Wt=Math.ceil(tw(l,14,600))+36,g=el('g',{class:'tt'},sprites);
 el('rect',{x:-Wt/2+1,y:-19,width:Wt-2,height:38,rx:6,fill:C[c][0],stroke:C[c][1],'stroke-width':1.2},g);
 const t=el('text',{x:0,y:1,'text-anchor':'middle','dominant-baseline':'central','font-size':14,'font-weight':600,fill:C[c][2]},g);t.textContent=l;
 const Y=1.1+(i%3)*.3+(i===0?.75:0);groups.push({i,Y,cx:px,cy:py,items:[{g,p:[(px-CX)*.056,Y,(py-CY)*.052],k:.82/40}]})});
FIGS.forEach(([r,px,py])=>{const g=el('g',{class:'tt'},sprites);
 g.innerHTML=`<g fill="none" stroke="#6B6A66" stroke-width="1.6" stroke-linecap="round"><circle cx="0" cy="-20" r="6"/><path d="M0 -14V12M0 12L-8 26M0 12L8 26M0 -10L-14 -6M0 -10L14 -6"/></g><rect x="-32" y="-9" width="64" height="18" rx="3" fill="#FFFFFF" stroke="#5F5E5A" stroke-width=".9"/><text x="0" y=".5" text-anchor="middle" dominant-baseline="central" font-size="11" font-weight="500" fill="#2C2C2A">${r}</text>`;
 let G=groups[0],bd=1e9;groups.forEach(q=>{const d=(q.cx-px)**2+(q.cy-py)**2;if(d<bd){bd=d;G=q}});G.items.push({g,p:[(px-CX)*.056,G.Y-.55,(py-CY)*.052],k:.92/56})});
const LT=el('text',{'text-anchor':'middle','dominant-baseline':'central','font-size':11,'font-weight':600,'letter-spacing':'1.1',fill:GRAY?'#2A2A2A':'#8A6410'},labels);LT.textContent='DIGITAL MEDIATION';
const LB=el('g',{},labels);
if(GRAY){LB.innerHTML=`<text x="0" y="-10" text-anchor="middle" dominant-baseline="central" font-size="11" font-weight="600" letter-spacing="1.1" fill="#111111">FUNDING</text>`;
 const wp=tw('PUBLIC',11,600)+6.6+10,wv=tw('PRIVATE',11,600)+7.7+10,gap=4,x0=-(wp+wv+gap)/2;
 LB.innerHTML+=`<rect x="${x0}" y="2" width="${wp}" height="17" rx="3" fill="#FFFFFF" stroke="#1E1E1E"/><text x="${x0+wp/2+.5}" y="11" text-anchor="middle" dominant-baseline="central" font-size="11" font-weight="600" letter-spacing="1.1" fill="#1E1E1E">PUBLIC</text><rect x="${x0+wp+gap}" y="2" width="${wv}" height="17" rx="3" fill="#1E1E1E" stroke="#1E1E1E"/><text x="${x0+wp+gap+wv/2+.5}" y="11" text-anchor="middle" dominant-baseline="central" font-size="11" font-weight="600" letter-spacing="1.1" fill="#FFFFFF">PRIVATE</text>`}
else LB.innerHTML=`<text x="0" y="0" text-anchor="middle" dominant-baseline="central" font-size="11" font-weight="600" letter-spacing="1.1" fill="#4B2A7A">FUNDING Â· <tspan fill="#A32D2D">PUBLIC</tspan> AND <tspan fill="#185FA5">PRIVATE</tspan></text>`;
meas.remove();
function render(a){setCam(a);sphere();const list=[];
 groups.forEach(G=>{const dy=.15*Math.sin(3*a+G.i*2.3);G.items.forEach(it=>{const q=P([it.p[0],it.p[1]+dy,it.p[2]]);list.push([q[2],it,q])})});
 list.sort((x,y)=>y[0]-x[0]);list.forEach(([z,it,q])=>{it.g.setAttribute('transform',`translate(${q[0].toFixed(2)},${q[1].toFixed(2)}) scale(${(F*it.k/z).toFixed(4)})`);sprites.appendChild(it.g)});
 const t=P([0,7.5,0]);LT.setAttribute('x',t[0]);LT.setAttribute('y',t[1]);
 const b=P([Math.sin(a)*2.8,-7.9,Math.cos(a)*2.8]);LB.setAttribute('transform',`translate(${b[0]},${b[1]})`)}
let t0=null,paused=false,ang=0,last=null;
function loop(ts){if(!root.__manual){if(last!==null&&!paused)ang+=(ts-last)/PERIOD*Math.PI*2;last=ts;render(ang)}requestAnimationFrame(loop)}
render(0);if(!(opts&&opts.manual))requestAnimationFrame(loop);
return{render,pause:v=>{paused=v}}}

(function(){const manual=location.hash==='#manual';const go=()=>{window.AS=ArtSphere(document.documentElement,'gray',{manual});};
if(document.fonts&&document.fonts.load)Promise.all([document.fonts.load('600 14px Plex'),document.fonts.load('500 11px Plex')]).then(go,go);else go();})();
